void _Cassette_Clamp(uint8_t _ctl)
{
    if(_ctl==1)    // 退盒
    {
        bsp_valve_Ctl(VALVE_BOX_IN,  0);
//       bsp_valve_Ctl(VALVE_BOX_OUT,  50);
			 bsp_valve_Ctl(VALVE_BOX_OUT,  65);
    }
    else  if(_ctl==0)      // 进盒
    {
        bsp_valve_Ctl(VALVE_BOX_OUT,  0);
//       bsp_valve_Ctl(VALVE_BOX_IN,  50);   
          bsp_valve_Ctl(VALVE_BOX_IN,  80);
    }
    else if (_ctl==2)   //进盒锁力矩
    {
        bsp_valve_Ctl(VALVE_BOX_OUT,  0);
//       bsp_valve_Ctl(VALVE_BOX_IN,  55);       
        bsp_valve_Ctl(VALVE_BOX_IN,  85);
		//	bsp_valve_Ctl(VALVE_BOX_IN,  100);
//        bsp_valve_Ctl(VALVE_BOX_IN,  clamp_duty);
    }
}

static void _Cassette_CtlAllValve(uint8_t _ctl)
{
    if (_ctl)
    {
        bsp_valve_Ctl(VALVE_INFUSION,  1);      //打开灌注阀门
        bsp_valve_Ctl(VALVE_REFLUX,  1);        //打开回流阀门
    }
    else
    {
        bsp_valve_Ctl(VALVE_INFUSION,  0);      //关闭灌注阀
        bsp_valve_Ctl(VALVE_REFLUX,  0);        //关闭回流阀门
    }
}


int  Cassette_Task_Init()
{
    ramdata._cassette_state._state =  CASSETTE_UNLOAD;
    Cassette_ctor();
    QActive_setAttr(AO_Cassette,THREAD_NAME_ATTR,"Casstte_qm");
    QACTIVE_START(AO_Cassette,QPC_CASSETTE_PRO,cassette__queueSto,Q_DIM(cassette__queueSto),cassette_task_stack,CASSETTE_TASK_SIZE,NULL);

}
INIT_APP_EXPORT(Cassette_Task_Init);

