static QState Cassette_initial(Cassette * const me, void const * const par) {
    //${AOs::Cassette::SM::initial}
    me->_state = CASSETTE_IDEL_STATE;
    QActive_subscribe(&me->super, CASSETTERELEASE_SIG);
    return Q_TRAN(&Cassette_Active);
}

//${AOs::Cassette::SM::Active} ...............................................
static QState Cassette_Active(Cassette * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Cassette::SM::Active::initial}
        case Q_INIT_SIG: {
            me->_errCode = 0;
            me->_state = CASSETTE_IDEL_STATE;
            ramdata._cassette_state._state =  CASSETTE_UNLOAD;
            ramdata._cassette_state._release_right = 0;
            ramdata._cassette_state._release_left = 0;
            _Cassette_CtlAllValve(1);        //打开所有阀门
            status_ = Q_TRAN(&Cassette_waitLoad);
            break;
        }
        default: {
            status_ = Q_SUPER(&QHsm_top);
            break;
        }
    }
    return status_;
}

//${AOs::Cassette::SM::Active::waitLoad} .....................................
static QState Cassette_waitLoad(Cassette * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Cassette::SM::Active::waitLoad}
        case Q_ENTRY_SIG: {
            me->_state = CASSETTE_WAITLOAD_STATE;
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Cassette::SM::Active::waitLoad}
        case Q_EXIT_SIG: {
            me->_prstate = CASSETTE_WAITLOAD_STATE;

            QTimeEvt_disarm(&me->_timEvt);    //关闭定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Cassette::SM::Active::waitLoad::CASSETTEIN}
        case CASSETTEIN_SIG: {
            _Cassette_Clamp(0);    //关闭夹爪
            QTimeEvt_disarm(&me->_timEvt);
            QTimeEvt_armX(&me->_timEvt, 3000, 0U); //等待刹车解除
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Cassette::SM::Active::waitLoad::CASS_LOCKED}
        case CASS_LOCKED_SIG: {
			_Cassette_Clamp(2);    //关闭夹爪
            _Cassette_CtlAllValve(0);        //关闭所有气缸
            status_ = Q_TRAN(&Cassette_WaitUnload);
            break;
        }
        case CASSETTERELEASE_SIG: {
            _Cassette_CtlAllValve(1);        //打开所有阀门
            _Cassette_Clamp(1);              //打开夹爪
            status_ = Q_TRAN(&Cassette_WaitReleaseCassette);
            break;
        }
        //${AOs::Cassette::SM::Active::waitLoad::TIMEOUT}
        case TIMEOUT_SIG: {
            me->_errCode = CASSETTE_CLAMP_ERROR;        //夹爪夹持失败
            status_ = Q_TRAN(&Cassette_Error_Deal);
            break;


//             _Cassette_Clamp(2);    //关闭夹爪
//             _Cassette_CtlAllValve(0);        //关闭所有气缸
//             status_ = Q_TRAN(&Cassette_WaitUnload);
//             break;
        }
        default: {
            status_ = Q_SUPER(&Cassette_Active);
            break;
        }
    }
    return status_;
}

//${AOs::Cassette::SM::WaitUnload} ...........................................
static QState Cassette_WaitUnload(Cassette * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Cassette::SM::WaitUnload}
        case Q_ENTRY_SIG: {
            QTimeEvt_disarm(&me->_timEvt);
            me->_state = CASSETTE_WAITUNLOAD_STATE;
            ramdata._cassette_state._state  =CASSETTE_LOAD;
            // ErigeEvt *pe = Q_NEW(ErigeEvt, CASSETTEINDOWN_SIG);
            // QACTIVE_PUBLISH(&pe->super,NULL);
//						QTimeEvt_disarm(&me->_timEvt);
            QTimeEvt_armX(&me->_timEvt, 1000, 0U); //等待盒子夹持稳定
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Cassette::SM::WaitUnload}
        case Q_EXIT_SIG: {
						QTimeEvt_disarm(&me->_timEvt);
            me->_prstate = CASSETTE_WAITUNLOAD_STATE;
            status_ = Q_HANDLED();
            break;
        }
        case TIMEOUT_SIG: {
            ErigeEvt *pe = Q_NEW(ErigeEvt, CASSETTEINDOWN_SIG);
            QACTIVE_PUBLISH(&pe->super,NULL);

            Suction_Task_Calibration(); //液流上盒重新校准
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Cassette::SM::WaitUnload::CASSETTERELEASE}
        case CASSETTERELEASE_SIG: {
            _Cassette_CtlAllValve(1);        //打开所有阀门
            _Cassette_Clamp(1);              //打开夹爪
            status_ = Q_TRAN(&Cassette_WaitReleaseCassette);
            break;
        }
        default: {
            status_ = Q_SUPER(&QHsm_top);
            break;
        }
    }
    return status_;
}

//${AOs::Cassette::SM::Error_Deal} ...........................................
static QState Cassette_Error_Deal(Cassette * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Cassette::SM::Error_Deal}
        case Q_ENTRY_SIG: {
            QTimeEvt_disarm(&me->_timEvt);
            QTimeEvt_armX(&me->_timEvt, 10, 0U); //启动定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Cassette::SM::Error_Deal::TIMEOUT}
        case TIMEOUT_SIG: {
            //${AOs::Cassette::SM::Error_Deal::TIMEOUT::[Error]}
            if (me->_errCode>0) {
                bsp_error_list_add(me->_errCode);
                status_ = Q_TRAN(&Cassette_ErrorLoad);
            }
            //${AOs::Cassette::SM::Error_Deal::TIMEOUT::[NoError]}
            else {
                // ErigeEvt *pe = Q_NEW(ErigeEvt, CASSETTEINDOWN_SIG);
                // QACTIVE_PUBLISH(&pe->super,NULL);
                status_ = Q_TRAN(&Cassette_WaitUnload);
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&QHsm_top);
            break;
        }
    }
    return status_;
}

//${AOs::Cassette::SM::ErrorLoad} ............................................
static QState Cassette_ErrorLoad(Cassette * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Cassette::SM::ErrorLoad}
        case Q_ENTRY_SIG: {
            me->_state = CASSETTE_LOADERROR_STATE;
            ramdata._cassette_state._state  =CASSETTE_LOADERROR;
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Cassette::SM::ErrorLoad}
        case Q_EXIT_SIG: {
            me->_prstate = CASSETTE_LOADERROR_STATE;
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Cassette::SM::ErrorLoad::CASSETTERELEASE}
        case CASSETTERELEASE_SIG: {
            _Cassette_CtlAllValve(1);        //打开所有阀门
            _Cassette_Clamp(1);              //打开夹爪
            status_ = Q_TRAN(&Cassette_WaitReleaseCassette);
            break;
        }
        default: {
            status_ = Q_SUPER(&QHsm_top);
            break;
        }
    }
    return status_;
}

//${AOs::Cassette::SM::WaitReleaseCassette} ..................................
static QState Cassette_WaitReleaseCassette(Cassette * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::Cassette::SM::WaitReleaseCassette}
        case Q_ENTRY_SIG: {
            QTimeEvt_disarm(&me->_timEvt);
            me->_state = CASSETTE_WAITRELEASE_STATE;
            ramdata._cassette_state._state  =CASSETTE_RELEASING;    //退盒中
            QTimeEvt_armX(&me->_timEvt, 2000, 0U); //等待刹车解除
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Cassette::SM::WaitReleaseCassette}
        case Q_EXIT_SIG: {
            me->_prstate = CASSETTE_WAITRELEASE_STATE;
            QTimeEvt_disarm(&me->_timEvt);    //关闭定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::Cassette::SM::WaitReleaseCasse~::CASSETTE_LEFT_ACTIVE}
        case CASSETTE_LEFT_ACTIVE_SIG: {
            ramdata._cassette_state._release_left  =1;
            bsp_valve_Ctl(VALVE_BOX_IN,0);
            bsp_valve_Ctl(VALVE_BOX_OUT,0);
            //${AOs::Cassette::SM::WaitReleaseCasse~::CASSETTE_LEFT_AC~::[ramdata._cassette_state._releas~}
            if (ramdata._cassette_state._release_right == 1) {
                status_ = Q_TRAN(&Cassette_Active);
            }
            //${AOs::Cassette::SM::WaitReleaseCasse~::CASSETTE_LEFT_AC~::[else]}
            else {
                status_ = Q_HANDLED();
            }
            break;
        }
        //${AOs::Cassette::SM::WaitReleaseCasse~::TIMEOUT}
        case TIMEOUT_SIG: {
            me->_errCode = CASSETTE_RELEASE_ERROR;        //退盒失败
            bsp_error_list_add(me->_errCode);
            status_ = Q_TRAN(&Cassette_Active);
            break;
        }
        //${AOs::Cassette::SM::WaitReleaseCasse~::CASSETTE_RIGHT_ACTIVE}
        case CASSETTE_RIGHT_ACTIVE_SIG: {
            ramdata._cassette_state._release_right  =1;
            bsp_valve_Ctl(VALVE_BOX_OUT,0);
            //${AOs::Cassette::SM::WaitReleaseCasse~::CASSETTE_RIGHT_A~::[ramdata._cassette_state._releas~}
            if (ramdata._cassette_state._release_left == 1) {
                status_ = Q_TRAN(&Cassette_Active);
            }
            //${AOs::Cassette::SM::WaitReleaseCasse~::CASSETTE_RIGHT_A~::[else]}
            else {
                status_ = Q_HANDLED();
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&QHsm_top);
            break;
        }
    }
    return status_;
}
